// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 1000000000000000000);
    }

    function testFuzz_property(address helper, uint256 amount) public {
        vm.assume(helper != address(0) && helper != address(this) && helper != address(c));
        vm.deal(helper, amount);
        c.OpenToThePublic();
        vm.prank(helper);
        (bool ok,) = address(c).call{value: c.currentBetLimit()}(
            abi.encodeWithSignature("wager()")
        );
        assertTrue(!ok && !c.hasPlayerWagered(helper) && c.ethBalance() == 0);
    }
}
